<?php
require_once 'config.php';require_role('student');$pageTitle='My applications';$s=$pdo->prepare('SELECT a.*,j.title,j.company_name,j.location,j.category,j.deadline FROM applications a JOIN jobs j ON j.id=a.job_id WHERE a.user_id=? ORDER BY a.applied_at DESC');$s->execute([current_user()['id']]);$apps=$s->fetchAll();require 'includes/header.php'; ?>
<section class="dashboard-hero"><div><div class="eyebrow"><span class="eyebrow-dot"></span> YOUR JOURNEY, IN ONE PLACE</div><h1>My <span class="text-accent">applications.</span></h1><p>Every application is progress. Here's where things stand.</p></div><a class="button button-primary" href="jobs.php">Find more opportunities ↗</a></section><section class="section dashboard-section"><div class="listing-heading"><div><h2>Application activity <span class="count-pill"><?= count($apps) ?></span></h2><p>Track the status of every opportunity you've applied for.</p></div></div><?php if($apps): ?><div class="application-list"><?php foreach($apps as $app): $statusClass=strtolower(str_replace(' ','-',$app['status'])); ?><article class="application-card"><div class="company-logo logo-<?= ((int)$app['id']%4)+1 ?>"><?= e(initials($app['company_name'])) ?></div><div class="application-main"><h3><a href="job.php?id=<?= (int)$app['job_id'] ?>"><?= e($app['title']) ?></a></h3><p><?= e($app['company_name']) ?></p><div class="job-meta"><span>⌖ <?= e($app['location']) ?></span><span>Applied <?= date('M j, Y',strtotime($app['applied_at'])) ?></span></div></div><div class="application-status"><span class="status-pill status-<?= e($statusClass) ?>"><i></i><?= e($app['status']) ?></span><a class="text-link" href="job.php?id=<?= (int)$app['job_id'] ?>">View role →</a></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><div class="empty-icon">↗</div><h3>Your story is still being written</h3><p>When you apply for a role, you'll be able to follow its progress right here.</p><a class="button button-primary" href="jobs.php">Explore opportunities ↗</a></div><?php endif; ?></section>
